// Replacement of the duel callback: the attacker always wins, with an
// attack value from 50 to 98 and a defence value from 1 to 18.
ScBtlCalc_CMDBTL <- function ( _cmdAtk, _cmdDef, _avtAtk, _avtDef )
{
	local trg = CMND_BTL_GET_RAND(50, 99);
	local tnm = CMND_BTL_GET_RAND(1, 19);
	CMND_BTL_SET_RESULT(true, trg, tnm, false);
};
